import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    while True:
        position = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.strip() and not line.lstrip().startswith("#"):
            stream.seek(position)
            break

    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        reader = csv.reader(stream, delimiter=",", quotechar='"')
        columns = next(reader, [])
        rows = list(reader)
    finally:
        csv.field_size_limit(old_limit)

    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    for index in range(len(columns), width):
        name = "extra_column_{}".format(index + 1)
        while name in used:
            name += "_"
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
